mapper.select:
SELECT
FROM user
AND username LIKE CONCAT('%', #{username}, '%')
AND name LIKE CONCAT('%', #{name}, '%')
AND status = #{status}
ORDER BY create_time DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.insert:
INSERT INTO user (
    username, password, name, phone, email, status, create_time, update_time
) VALUES (
             #{username}, #{password}, #{name}, #{phone}, #{email}, #{status}, NOW(), NOW()
         )

mapper.update:
UPDATE user
SET password = #{newPassword}, update_time = NOW()
WHERE id = #{id}

UPDATE user
SET status = #{status}, update_time = NOW()
WHERE id = #{id}
